/** Module declaration and span capture (0004 §2). */
import { register } from "./graph.js";
/** Pipeline order for the class style (0007 §verify). */
const PIPELINE_PHASES = ["fetch", "build", "install", "config", "verify", "activate"];
/**
 * Base class for the class authoring style (0007 §1).
 *
 * Subclass and override any phase method — each returns a step, a list
 * of steps, or nothing. The pipeline chains phases in order and
 * sequences steps within each phase, filling only *empty* `needs` —
 * explicit `needs` always win. Register with {@link define}.
 *
 * **Phase methods run at eval time only** — they build IR, they never
 * run while your system is being built.
 *
 * @example
 * ```ts
 * class Helix extends Module {
 *   override fetch() {
 *     return fetchStep(githubRelease({ repo: "helix-editor/helix", asset: "h.tar.xz" }));
 *   }
 *   override install() {
 *     return installStep({ "bin/hx": symlink("~/.local/bin/hx") });
 *   }
 * }
 * define(Helix);
 * ```
 */
export class Module {
    /** Module name; defaults to the class name lowercased. */
    static moduleName;
    fetch() {
        return;
    }
    build() {
        return;
    }
    install() {
        return;
    }
    config() {
        return;
    }
    verify() {
        return;
    }
    activate() {
        return;
    }
}
function normalize(result, phase) {
    if (!result)
        return [];
    const steps = Array.isArray(result) ? result : [result];
    return steps.map((s) => (s.phase === undefined ? { ...s, phase } : s));
}
function collectPipeline(instance) {
    const chained = [];
    for (const phase of PIPELINE_PHASES) {
        for (const s of normalize(instance[phase](), phase)) {
            const prev = chained[chained.length - 1];
            chained.push(s.needs === undefined && prev ? { ...s, needs: [prev.id] } : s);
        }
    }
    return chained;
}
/** Capture the first stack frame outside this file (V8: file:line:col). */
function callerSpan() {
    const here = new URL(import.meta.url).pathname;
    const stack = new Error().stack;
    if (!stack)
        return undefined;
    for (const line of stack.split("\n").slice(1)) {
        const m = line.match(/\(?([^()\s]+):(\d+):(\d+)\)?$/);
        if (m && m[1] && !m[1].endsWith(here)) {
            const file = m[1].replace(/^file:\/\//, "");
            return { file, line: Number(m[2]), col: Number(m[3]) };
        }
    }
    return undefined;
}
/** Declare a module from declarative fields (data style). */
export function module(name, spec) {
    const ir = {};
    if (spec.fetch)
        ir.fetch = spec.fetch;
    if (spec.build)
        ir.build = spec.build;
    const entries = (rec) => rec && Object.keys(rec).length > 0
        ? Object.entries(rec).map(([from, d]) => ({ from, to: d.to, mode: d.mode }))
        : undefined;
    const install = entries(spec.install);
    if (install)
        ir.install = install;
    const config = entries(spec.config);
    if (config)
        ir.config = config;
    if (spec.depends?.length)
        ir.depends = spec.depends;
    if (spec.activate?.length)
        ir.activate = spec.activate;
    if (spec.steps?.length)
        ir.steps = spec.steps;
    if (spec.verify)
        ir.verify = spec.verify;
    if (spec.retries !== undefined)
        ir.retries = spec.retries;
    const span = callerSpan();
    if (span)
        ir.span = span;
    register(name, ir);
}
/** Instantiate a class-style module and register it (see {@link Module}). */
export function define(ctor) {
    const instance = new ctor();
    const ir = { steps: collectPipeline(instance) };
    const span = callerSpan();
    if (span)
        ir.span = span;
    const named = ctor;
    register(named.moduleName ?? ctor.name.toLowerCase(), ir);
}
